run:
if ($env:SQL_ABC_CONTROLLER -cnotmatch '\A[0-9a-f]{40}\z' -or $env:SQL_ABC_CONTROLLER -ceq ('0'*40) -or
    $env:GITHUB_REF -cne 'refs/heads/master' -or $env:GITHUB_EVENT_NAME -cne 'workflow_dispatch' -or
    $env:GITHUB_RUN_ATTEMPT -cne '1' -or $env:GITHUB_REPOSITORY -cne 'GarvanFairy/GarageSaas') {
  throw 'Reviewed default-branch controller enrollment and separate execution approval required.'
}

$mapping = @{ A='050458d658505f787a49aced52f9a21f1aa2fb75'; B='820890d205a1a4f73defda03ce854acc04068001'; C='2ebca1cb613520b1e60b5fc65ceb3b680b8a89f9' }
$controller = git -C controller rev-parse HEAD
if ($LASTEXITCODE -ne 0 -or $controller -cne $env:SQL_ABC_CONTROLLER) { throw 'Controller identity mismatch.' }
git -C controller merge-base --is-ancestor $env:SQL_ABC_CONTROLLER origin/master
if ($LASTEXITCODE -ne 0) { throw 'Controller is not on the default branch.' }
$application = git -C application rev-parse HEAD
if ($LASTEXITCODE -ne 0 -or $application -cne $mapping['${{ matrix.arm }}']) { throw 'Application identity mismatch.' }
